*{box-sizing:border-box} :root{--paper:#f3f1e9;--panel:#fffefa;--ink:#202a24;--muted:#7d827b;--line:#e6e4da;--green:#254637;--green2:#426b51;--mint:#e7eee6;--orange:#d47b49;--yellow:#eabf67;--red:#b95846;--shadow:0 10px 28px rgba(37,54,43,.045)}
body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px}button,input,select{font:inherit}button{cursor:pointer} .app-shell{min-height:100vh;display:flex}.sidebar{width:242px;flex-shrink:0;background:#f8f7f1;border-right:1px solid #e7e5dc;display:flex;flex-direction:column;padding:27px 17px 18px;position:fixed;inset:0 auto 0 0;z-index:5}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:inherit;padding:0 9px;margin-bottom:32px}.brand-mark{width:35px;height:35px;background:var(--green);color:#f5f2e7;border-radius:10px;display:grid;place-items:center;font-family:Manrope,sans-serif;font-weight:800;font-size:23px;font-style:italic;box-shadow:inset -6px -5px 0 rgba(0,0,0,.1)}.brand-name{font-family:Manrope,sans-serif;font-size:15px;font-weight:800;letter-spacing:1.55px;line-height:1.08}.brand-name small{display:block;font:500 8px 'DM Mono',monospace;letter-spacing:1.38px;color:#8a8d83;margin-top:5px}.company-switch{height:42px;border:1px solid var(--line);border-radius:8px;display:flex;align-items:center;padding:0 11px;gap:9px;font-size:12px;font-weight:700;margin:0 2px 32px;background:#fffefa}.company-dot{width:8px;height:8px;border-radius:50%;background:#c7774b}.chevron{margin-left:auto;color:#8e918a;font-size:17px}.nav-caption{font:500 9px 'DM Mono',monospace;letter-spacing:1.25px;color:#a0a097;padding:0 10px;margin-bottom:10px}.nav-item{width:100%;height:43px;border:0;background:none;color:#70776e;display:flex;align-items:center;gap:12px;padding:0 11px;border-radius:7px;text-align:left;font-size:12px;font-weight:600;margin:2px 0;transition:.18s}.nav-item:hover{background:#eeeee7;color:var(--ink)}.nav-item.active{background:#e8ede6;color:var(--green);font-weight:700}.nav-icon{width:17px;text-align:center;font-size:17px;color:#82887f}.nav-item.active .nav-icon{color:var(--green)}.nav-count{margin-left:auto;font:500 10px 'DM Mono',monospace;color:#718174;background:#fffefa;border:1px solid #dfe5dd;border-radius:5px;padding:3px 6px}.sidebar-bottom{margin-top:auto}.year-card{padding:14px 14px 13px;background:#eeefe7;border-radius:9px;margin:0 2px 15px}.year-card-top{display:flex;justify-content:space-between;align-items:center;font:500 8px 'DM Mono',monospace;letter-spacing:.8px;color:#858b81}.live-dot{height:6px;width:6px;background:#73946e;border-radius:50%;box-shadow:0 0 0 3px #dce5d8}.year-card strong{display:block;font:700 29px Manrope,sans-serif;margin:8px 0 0;color:var(--green)}.year-sub{font-size:10px;color:#8c9088;margin-top:1px}.reset-link{border:0;background:none;color:#85877f;font-size:10px;padding:7px 10px}.reset-link:hover{color:var(--red)}
.main-area{margin-left:242px;min-width:0;flex:1;display:flex;flex-direction:column;min-height:100vh}.topbar{height:72px;border-bottom:1px solid #e7e5dc;background:rgba(248,247,241,.82);display:flex;align-items:center;justify-content:space-between;padding:0 38px;position:sticky;top:0;z-index:4;backdrop-filter:blur(16px)}.breadcrumb{display:flex;gap:11px;align-items:center;color:#8c9087;font:500 9px 'DM Mono',monospace;letter-spacing:1px}.crumb-slash{color:#c3c4bb}.breadcrumb strong{color:#333d35;font-weight:500}.top-actions{display:flex;align-items:center;gap:19px}.top-stat{display:flex;align-items:center;gap:9px}.top-stat small{display:block;color:#92958b;font:500 8px 'DM Mono',monospace;letter-spacing:.75px;margin-bottom:3px}.top-stat strong{font:700 12px Manrope,sans-serif;white-space:nowrap}.top-stat strong em{font:500 9px 'DM Mono',monospace;font-style:normal;color:#7f867d}.stat-icon{display:grid;place-items:center;border-radius:7px;width:29px;height:29px;font-size:13px;font-weight:700}.money-icon{background:#e9eee5;color:#456745}.research-icon{background:#f5eede;color:#b48645}.top-divider{height:27px;border-left:1px solid var(--line)}.advance-btn{border:0;border-radius:6px;background:var(--green);color:#fffdf6;padding:10px 14px;font-size:11px;font-weight:700;letter-spacing:.1px;box-shadow:0 3px 7px rgba(37,70,55,.13);transition:.18s}.advance-btn:hover{background:#345b46;transform:translateY(-1px)}.advance-btn span{margin-right:7px;color:#b8d29b}.content{max-width:1450px;width:100%;margin:0 auto;padding:31px 38px 38px;flex:1}.footer{height:48px;border-top:1px solid #e7e5dc;padding:0 38px;display:flex;justify-content:space-between;align-items:center;font:500 8px 'DM Mono',monospace;letter-spacing:.7px;color:#a0a197}.footer-star{color:#c7834c;margin-left:4px}.mobile-brand{display:none}
.page-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:22px}.eyebrow{font:500 9px 'DM Mono',monospace;letter-spacing:1.35px;color:#90958a;text-transform:uppercase;margin-bottom:9px}.page-head h1{font:700 29px Manrope,sans-serif;letter-spacing:-1.1px;margin:0;color:#25332a}.page-head p{margin:7px 0 0;color:#858a80;font-size:12px}.date-pill{border:1px solid #e3e1d7;background:#f8f7f1;border-radius:20px;padding:7px 11px;font:500 9px 'DM Mono',monospace;color:#777e74}.date-pill b{color:#354b3a;font-weight:500}.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(270px,.82fr);gap:17px}.hero-card{background:var(--green);color:#fffdf6;border-radius:11px;min-height:285px;position:relative;overflow:hidden;padding:24px 26px;box-shadow:var(--shadow)}.hero-card:after{content:'';position:absolute;width:420px;height:420px;border-radius:50%;border:1px solid rgba(255,255,255,.085);right:-86px;top:-180px;box-shadow:0 0 0 35px rgba(255,255,255,.025),0 0 0 72px rgba(255,255,255,.02)}.hero-top{display:flex;justify-content:space-between;position:relative;z-index:1}.hero-kicker{font:500 9px 'DM Mono',monospace;letter-spacing:1.15px;color:#b7c8b3}.hero-badge{border:1px solid rgba(235,240,226,.25);border-radius:20px;padding:6px 9px;color:#cfddc5;font:500 8px 'DM Mono',monospace;letter-spacing:.6px}.hero-card h2{font:600 25px Manrope,sans-serif;letter-spacing:-.7px;margin:15px 0 5px;max-width:400px;position:relative;z-index:1}.hero-card p{color:#d0dbcf;font-size:11px;line-height:1.6;margin:0;max-width:310px;position:relative;z-index:1}.hero-actions{display:flex;gap:8px;margin-top:19px;position:relative;z-index:2}.btn-light{background:#f4f2e9;border:1px solid #f4f2e9;color:#344a3a;padding:9px 12px;border-radius:5px;font-size:10px;font-weight:700}.btn-ghost-light{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.25);color:#f5f5ec;padding:9px 12px;border-radius:5px;font-size:10px;font-weight:600}.hero-illustration{position:absolute;right:5%;bottom:16px;width:46%;height:145px;z-index:1}.hero-illustration svg{width:100%;height:100%;overflow:visible}.hero-illustration .car-shadow{fill:#162c21;opacity:.34}.hero-illustration .car-body{fill:#d28a5c}.hero-illustration .car-glass{fill:#d4dfd3}.hero-illustration .wheel{fill:#203229}.hero-illustration .hub{fill:#adbca6}.hero-illustration .car-line{stroke:#f2c397;stroke-width:1.5;fill:none;opacity:.75}.hero-illustration .road-line{stroke:#a8b99c;stroke-width:1;stroke-dasharray:3 6;opacity:.4}
.metric-row{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:16px 0}.metric-card{background:#fffefa;border:1px solid #eae8df;border-radius:8px;padding:13px 15px;box-shadow:var(--shadow);min-width:0}.metric-label{font:500 8px 'DM Mono',monospace;letter-spacing:.85px;color:#96998f;display:flex;align-items:center;justify-content:space-between}.metric-label i{font-style:normal;font-size:12px;color:#b2b5ab}.metric-value{font:700 21px Manrope,sans-serif;color:#2c3b30;margin:9px 0 3px;letter-spacing:-.6px}.metric-foot{font-size:9px;color:#91958c}.metric-foot .up{color:#59845c}.metric-foot .neutral{color:#b17d4b}.section-row{display:flex;justify-content:space-between;align-items:center;margin:22px 0 10px}.section-title{font:700 14px Manrope,sans-serif;margin:0;letter-spacing:-.2px}.section-meta{font:500 9px 'DM Mono',monospace;color:#96998f}.panel{background:#fffefa;border:1px solid #e9e7de;border-radius:9px;box-shadow:var(--shadow)}
.dash-lower{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.78fr);gap:16px}.fleet-panel{padding:16px}.panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.panel-head h3{margin:0;font:700 12px Manrope,sans-serif}.panel-head span{font:500 8px 'DM Mono',monospace;color:#92958b}.vehicle-row{display:flex;align-items:center;gap:13px;padding:12px 0;border-top:1px solid #f0eee7}.vehicle-thumb{width:83px;height:49px;border-radius:6px;background:#edf0e8;display:grid;place-items:center;flex-shrink:0}.vehicle-thumb svg{width:75px;height:42px}.vehicle-info{min-width:0;flex:1}.vehicle-info strong{display:block;font:700 11px Manrope,sans-serif}.vehicle-info small{color:#8e938a;font-size:9px}.vehicle-state{font:500 8px 'DM Mono',monospace;color:#57805b;background:#eaf1e7;border-radius:10px;padding:5px 8px}.vehicle-right{text-align:right;min-width:72px}.vehicle-right strong{font:700 11px Manrope,sans-serif;display:block}.vehicle-right small{font-size:8px;color:#92958b}.side-stack{display:flex;flex-direction:column;gap:12px}.quick-panel{padding:16px}.quick-panel h3{font:700 12px Manrope,sans-serif;margin:0 0 11px}.quick-action{width:100%;background:#fffefa;border:1px solid #eae8df;border-radius:6px;display:flex;align-items:center;text-align:left;padding:9px 10px;margin:6px 0;gap:10px}.quick-action:hover{border-color:#b9c9b9;background:#f8faf5}.quick-symbol{width:27px;height:27px;display:grid;place-items:center;border-radius:6px;background:#eef1e8;color:#496649;font-size:14px}.quick-action span:nth-child(2){font-size:10px;font-weight:700;color:#354138}.quick-action small{display:block;color:#92958b;font-size:8px;font-weight:400;margin-top:2px}.quick-arrow{margin-left:auto;color:#999d94}.news-panel{padding:15px 16px;background:#f0efe7}.news-title{font:500 8px 'DM Mono',monospace;letter-spacing:.9px;color:#96998f;margin-bottom:9px}.news-item{font-size:10px;line-height:1.45;color:#656e63}.news-item b{color:#405643}.empty-state{text-align:center;padding:19px 12px;color:#8a9085;font-size:10px}
/* shared controls */
.btn-primary,.btn-secondary,.btn-danger{border:1px solid var(--green);background:var(--green);color:#fffdf6;border-radius:5px;padding:10px 13px;font-size:10px;font-weight:700;transition:.17s}.btn-primary:hover{background:#365b45;transform:translateY(-1px)}.btn-primary:disabled{opacity:.42;cursor:not-allowed;transform:none}.btn-secondary{background:#fffefa;border-color:#dedfd5;color:#49584a}.btn-secondary:hover{background:#f2f4ed;border-color:#b8c5b4}.btn-danger{background:#fff8f4;border-color:#ead6cb;color:#a4513e}.input-label{display:block;color:#7e857c;font:500 8px 'DM Mono',monospace;letter-spacing:.8px;margin:0 0 6px;text-transform:uppercase}.text-input,.select-input{height:37px;width:100%;border:1px solid #e2e2d9;background:#fffefa;border-radius:5px;padding:0 10px;color:#344338;font-size:11px;outline:none}.text-input:focus,.select-input:focus{border-color:#8fa58c;box-shadow:0 0 0 2px #e8eee5}.control-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inline-control{display:flex;align-items:center;gap:8px}.inline-control input[type=range]{width:100%;accent-color:#537a5b}.range-val{font:500 9px 'DM Mono',monospace;color:#4f6c51;min-width:29px;text-align:right}.tag{display:inline-flex;border-radius:12px;padding:5px 8px;background:#edf1e9;color:#5a795b;font:500 8px 'DM Mono',monospace}.small-note{font-size:9px;color:#92968d;line-height:1.5}.divider{border:0;border-top:1px solid #efeee8;margin:15px 0}
@media(max-width:1050px){.sidebar{width:210px}.main-area{margin-left:210px}.topbar{padding:0 24px}.content{padding:27px 24px}.hero-illustration{right:1%;width:41%}.overview-grid,.dash-lower{grid-template-columns:minmax(0,1.3fr) minmax(240px,.8fr)}}
@media(max-width:760px){.sidebar{width:100%;height:auto;inset:auto 0 0;top:auto;border-right:0;border-top:1px solid #e4e3d9;padding:5px 8px calc(5px + env(safe-area-inset-bottom));display:block}.brand,.company-switch,.nav-caption,.sidebar-bottom{display:none}.sidebar nav{display:grid;grid-template-columns:repeat(5,1fr);gap:2px}.nav-item{height:48px;margin:0;padding:4px 2px;justify-content:center;flex-direction:column;gap:2px;font-size:8px;border-radius:6px}.nav-icon{font-size:16px}.nav-count{display:none}.main-area{margin-left:0;padding-bottom:61px}.topbar{height:58px;padding:0 14px}.mobile-brand{display:flex;align-items:center;gap:7px;font:800 11px Manrope,sans-serif;letter-spacing:1px}.mobile-brand .brand-mark{width:27px;height:27px;font-size:18px;border-radius:7px}.breadcrumb{display:none}.top-actions{gap:9px}.top-stat{gap:5px}.stat-icon{width:24px;height:24px;font-size:11px}.top-stat small{font-size:7px}.top-stat strong{font-size:10px}.top-divider{height:22px}.advance-btn{padding:9px 9px;font-size:9px}.advance-btn span{margin-right:3px}.content{padding:22px 14px 24px}.page-head{align-items:flex-start;margin-bottom:16px}.page-head h1{font-size:24px}.page-head p{font-size:10px;max-width:260px}.date-pill{font-size:8px;padding:6px 8px}.overview-grid,.dash-lower{grid-template-columns:1fr}.hero-card{min-height:265px;padding:20px}.hero-card h2{font-size:22px;max-width:270px}.hero-card p{max-width:245px}.hero-illustration{width:53%;height:112px;right:2%;bottom:12px}.metric-row{grid-template-columns:repeat(2,1fr);gap:8px;margin:12px 0}.metric-card{padding:11px}.metric-value{font-size:19px}.side-stack{display:grid;grid-template-columns:1fr 1fr}.quick-panel,.news-panel{padding:12px}.footer{padding:0 14px;font-size:7px}.footer span:last-child{display:none}}
@media(max-width:390px){.top-actions{gap:6px}.top-stat small{display:none}.top-stat{gap:3px}.advance-btn{font-size:8px;padding:8px 7px}.side-stack{grid-template-columns:1fr}.hero-illustration{opacity:.85;width:56%}}

/* Design studio */
.studio-layout{display:grid;grid-template-columns:minmax(0,1.28fr) minmax(285px,.82fr);gap:16px;align-items:start}.studio-main,.studio-side{display:flex;flex-direction:column;gap:12px}.studio-card{padding:17px}.studio-card h3{font:700 12px Manrope,sans-serif;margin:0}.studio-card .card-sub{font-size:9px;color:#92968c;margin:5px 0 14px}.design-preview{background:#e8ede5;border-radius:8px;min-height:180px;display:grid;place-items:center;position:relative;overflow:hidden}.design-preview:before{content:'';position:absolute;inset:auto 0 31px;border-top:1px dashed rgba(83,107,82,.24)}.design-car{width:90%;max-width:510px;position:relative;z-index:1}.design-car svg{width:100%;height:auto}.design-car .body{fill:var(--car-color,#c77950);transition:.2s}.design-car .glass{fill:#cbd8d0}.design-car .tire{fill:#25352d}.design-car .rim{fill:#d7ddd1}.design-car .detail{stroke:#f3c6a1;stroke-width:2;fill:none}.preview-label{position:absolute;left:13px;top:11px;font:500 8px 'DM Mono',monospace;color:#71816f;letter-spacing:.8px}.swatch-row{display:flex;gap:7px;margin-top:12px}.swatch{width:20px;height:20px;border:2px solid #fffefa;box-shadow:0 0 0 1px #dedfd5;border-radius:50%;padding:0}.swatch.selected{box-shadow:0 0 0 2px #456d4c}.field-group{margin:12px 0}.choice-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.choice-card{min-height:56px;padding:8px 7px;border:1px solid #e8e7de;background:#fffefa;border-radius:6px;text-align:left;color:#536054}.choice-card:hover{border-color:#b1c2af}.choice-card.selected{background:#eff3ec;border-color:#96ab92;color:#36573b;box-shadow:inset 0 0 0 1px #d8e2d5}.choice-card strong{display:block;font:700 9px Manrope,sans-serif}.choice-card small{display:block;font-size:8px;color:#91958c;margin-top:4px}.range-line{display:flex;align-items:center;justify-content:space-between;margin:9px 0 5px}.range-line span{font-size:10px;color:#59645b}.design-summary{background:#f1f3eb;border-radius:7px;padding:12px}.design-summary-line{display:flex;justify-content:space-between;margin:6px 0;color:#7f887b;font-size:9px}.design-summary-line strong{color:#405543;font:600 9px 'DM Mono',monospace}.rating-bars{display:grid;gap:9px}.rating-row{display:grid;grid-template-columns:74px 1fr 25px;align-items:center;gap:9px;font-size:9px;color:#737b70}.rating-track{height:5px;background:#edf0e9;border-radius:5px;overflow:hidden}.rating-fill{height:100%;border-radius:5px;background:#6c9068}.rating-row b{text-align:right;font:500 9px 'DM Mono',monospace;color:#596a58}.studio-actions{display:flex;gap:7px;margin-top:13px}.studio-actions button{flex:1}.launch-banner{background:#f5eee2;border:1px solid #efe4d2;color:#8f7048;border-radius:6px;padding:10px;font-size:9px;line-height:1.5;margin-top:10px}
/* labs / team / market */
.resource-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px}.resource-box{background:#fffefa;border:1px solid #e8e6dd;border-radius:8px;padding:13px}.resource-box span{display:block;color:#92968d;font:500 8px 'DM Mono',monospace;letter-spacing:.7px}.resource-box strong{display:block;margin-top:7px;font:700 19px Manrope,sans-serif;color:#314336}.research-layout,.people-layout,.market-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,.78fr);gap:15px;align-items:start}.research-list{display:flex;flex-direction:column;gap:8px}.tech-row{display:flex;align-items:center;gap:13px;padding:13px;border:1px solid #e9e7de;border-radius:7px;background:#fffefa}.tech-icon{width:35px;height:35px;border-radius:8px;background:#eef0e8;color:#55734f;display:grid;place-items:center;font-size:17px;flex-shrink:0}.tech-data{flex:1;min-width:0}.tech-data strong{font:700 10px Manrope,sans-serif;display:block}.tech-data p{font-size:9px;color:#8b9087;margin:4px 0}.tech-meta{font:500 8px 'DM Mono',monospace;color:#9a9c92}.tech-action{min-width:87px;text-align:right}.tech-action .btn-primary,.tech-action .btn-secondary{padding:8px 9px;font-size:8px}.locked-label{color:#a1a39b;font:500 8px 'DM Mono',monospace}.lab-side,.team-card,.market-card{padding:16px}.lab-side h3,.team-card h3,.market-card h3{font:700 12px Manrope,sans-serif;margin:0 0 12px}.researcher-count{display:flex;align-items:center;justify-content:space-between;padding:11px 0;border-top:1px solid #efeee8}.researcher-count span{font-size:10px;color:#677165}.researcher-count strong{font:700 12px Manrope,sans-serif}.person-actions{display:flex;gap:7px;margin-top:12px}.person-actions button{flex:1;padding:9px 4px;font-size:9px}.employee-line{display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-top:1px solid #efeee8;font-size:10px}.employee-line span{color:#6e786e}.employee-line strong{font:600 10px 'DM Mono',monospace;color:#435343}.building-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.building-card{border:1px solid #e8e7df;border-radius:7px;padding:13px;background:#fffefa}.building-icon{font-size:18px;color:#72866d}.building-card h4{font:700 10px Manrope,sans-serif;margin:8px 0 4px}.building-card p{font-size:8px;color:#8f938a;line-height:1.5;min-height:24px;margin:0 0 10px}.building-card button{width:100%;padding:8px 3px;font-size:8px}.factory-cap{height:6px;background:#eeefe8;border-radius:5px;margin:9px 0 4px}.factory-cap i{display:block;height:100%;background:#668765;border-radius:5px}.capacity-legend{display:flex;justify-content:space-between;color:#979a90;font:500 8px 'DM Mono',monospace}.region-row{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #efeee8;padding:11px 0}.region-row strong{font:700 10px Manrope,sans-serif}.region-row small{display:block;font-size:8px;color:#92968c;margin-top:3px}.region-row button{font-size:8px;padding:7px 8px}.finance-chart{height:145px;display:flex;align-items:flex-end;gap:9px;padding:10px 4px 0;border-bottom:1px solid #eae9e1}.chart-bar{flex:1;min-width:12px;max-width:48px;background:#95a98b;border-radius:4px 4px 0 0;position:relative;transition:.3s}.chart-bar.current{background:#d28a5c}.chart-bar span{position:absolute;bottom:-17px;left:50%;transform:translateX(-50%);font:500 7px 'DM Mono',monospace;color:#92968b}.chart-caption{display:flex;justify-content:space-between;font-size:9px;color:#858b81;margin-top:24px}.insight-card{padding:14px;background:#f1f2eb;border-radius:7px;margin-top:10px}.insight-card strong{font:700 10px Manrope,sans-serif;color:#445844}.insight-card p{font-size:9px;color:#7b8478;line-height:1.55;margin:5px 0 0}.analysis-card{padding:16px;border-left:3px solid #d18a58}.analysis-card h3{font:700 12px Manrope,sans-serif;margin:0 0 7px}.analysis-card p{font-size:9px;color:#80877e;line-height:1.5;margin:0}
/* modal and notification */
