const STORAGE_KEY='motorhaus-save-v1';
const techTree=[
 {id:'radial',name:'Radial tyres',year:2000,cost:3,icon:'◉',desc:'Longer tyre life and steadier handling.',effect:'Comfort +5 · quality +2'},
 {id:'aero',name:'Wind-tunnel testing',year:2001,cost:4,icon:'〰',desc:'Shape bodywork to cut drag and cabin noise.',effect:'Design +5 · efficiency +4'},
