const bodies=[{id:'sedan',name:'Sedan',detail:'Balanced family car',base:0},{id:'coupe',name:'Coupe',detail:'Sporty two-door',base:4},{id:'hatch',name:'Hatchback',detail:'Practical city car',base:2},{id:'pickup',name:'Pickup',detail:'Hard-working utility',base:1,tech:'truck'},{id:'jeep',name:'Jeep',detail:'Rugged off-road',base:3,tech:'truck'},{id:'smalltruck',name:'Small truck',detail:'Compact cargo hauler',base:1,tech:'truck'},{id:'truck',name:'Heavy truck',detail:'Big commercial rig',base:0,tech:'truck'}];
const palettes=[{name:'Copper',hex:'#c77950'},{name:'Pine',hex:'#55775b'},{name:'Cream',hex:'#d9cba5'},{name:'Navy',hex:'#536b7d'},{name:'Brick',hex:'#a95042'},{name:'Graphite',hex:'#71736d'}];
const names=['Morrow 01','Morrow Touring','Morrow Scout','Morrow City'];
const defaultState=()=>({company:'Morrow Motor Co.',year:2000,cash:2000,rp:0,researchers:0,fixers:0,buildings:1,regions:['Home market'],tech:[],models:[],draft:{name:'Morrow 01',body:'sedan',shape:50,size:50,interior:50,tires:'touring',color:palettes[0].hex,price:16000},lastYear:null,history:[],lastReport:null,modelNo:1});
let state=loadState();let activeView='overview';let toastTimer;
function loadState(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));return s?{...defaultState(),...s,draft:{...defaultState().draft,...s.draft}}:defaultState()}catch{return defaultState()}}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateHeader()}
function money(n){return '$'+Math.round(n).toLocaleString('en-US')}
function clamp(n,min=0,max=100){return Math.max(min,Math.min(max,n))}
function bodyInfo(id){return bodies.find(b=>b.id===id)||bodies[0]}
function techCount(){return state.tech.length}
function techHas(id){return state.tech.includes(id)}
function draftScores(d=state.draft){let research=techCount();let body=bodyInfo(d.body);let techScore=clamp(35+research*5+(techHas('injection')?7:0)+(techHas('safety')?6:0)+(techHas('hybrid')?10:0)+(techHas('turbo')?12:0)+(techHas('electric')?17:0)+(techHas('navigation')?5:0)+(techHas('autonomy')?12:0));let design=clamp(48+body.base+Math.round((d.shape-50)*.28)+(d.tires==='sport'?4:d.tires==='utility'?1:0)+(techHas('aero')?5:0));let comfort=clamp(47+Math.round((d.interior-50)*.32)+(d.tires==='touring'?4:0)+(techHas('radial')?5:0)+(techHas('safety')?2:0)+(techHas('navigation')?6:0));let fix=state.fixers*6;let quality=clamp(Math.round((design+techScore+comfort)/3)+fix);return{design:clamp(design+Math.min(15,fix)),technology:techScore,comfort:clamp(comfort+Math.min(15,fix)),quality}}
function updateHeader(){let c=document.getElementById('cashTop');if(!c)return;c.textContent=money(state.cash);document.getElementById('rpTop').innerHTML=`${state.rp} <em>RP</em>`;document.getElementById('sideYear').textContent=state.year;document.getElementById('footerYear').textContent=state.year;document.getElementById('companyLabel').textContent=state.company;document.getElementById('researchNav').textContent=state.rp}
function toast(message){let el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function setView(view){activeView=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('crumbTitle').textContent=({overview:'OVERVIEW',design:'DESIGN STUDIO',research:'RESEARCH LAB',people:'PEOPLE & SITES',market:'MARKET'})[view];render()}
document.getElementById('mainNav').addEventListener('click',e=>{let b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});
document.getElementById('advanceBtn').addEventListener('click',advanceYear);
document.getElementById('resetBtn').addEventListener('click',()=>showModal('Start fresh?','A new company will erase this save. This cannot be undone.','Start over',()=>{localStorage.removeItem(STORAGE_KEY);state=defaultState();activeView='overview';render();toast('A new company, a clean sheet.')}));
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
function showModal(title,body,confirmText,onConfirm,extra=''){let modal=document.getElementById('modal');modal.innerHTML=`<h2>${title}</h2><p>${body}</p>${extra}<div class="modal-actions"><button class="btn-secondary" id="modalCancel">Cancel</button><button class="btn-primary" id="modalConfirm">${confirmText}</button></div>`;document.getElementById('modalBackdrop').hidden=false;document.getElementById('modalCancel').onclick=closeModal;document.getElementById('modalConfirm').onclick=()=>{closeModal();onConfirm()}}
function closeModal(){document.getElementById('modalBackdrop').hidden=true}
function render(){updateHeader();document.getElementById('appContent').innerHTML=({overview:overviewPage,design:designPage,research:researchPage,people:peoplePage,market:marketPage}[activeView])()}
function pageHead(title,sub,tag=''){return `<div class="page-head"><div><div class="eyebrow">${tag||state.company}</div><h1>${title}</h1><p>${sub}</p></div><div class="date-pill">MODEL YEAR &nbsp;<b>${state.year}</b></div></div>`}
function carSvg(color=state.draft.color){return `<svg viewBox="0 0 480 150" role="img" aria-label="Vehicle design preview"><ellipse class="car-shadow" cx="245" cy="122" rx="188" ry="13"/><path class="road-line" d="M35 127h410"/><path class="car-body" style="fill:${color}" d="M59 102 73 79q5-8 20-12l67-18 40-30q9-7 25-7h76q16 0 25 10l38 39 48 10q11 3 15 13l9 18q3 8-7 8H67q-14 0-8-8Z"/><path class="car-glass" d="m166 64 41-31q7-5 18-5h32v36Zm102-36h31q9 0 16 7l28 29h-75Z"/><path class="car-line" d="M64 99h337M211 31l-9 37m73-40v36m48 0 1 32"/><circle class="wheel" cx="139" cy="108" r="24"/><circle class="wheel" cx="342" cy="108" r="24"/><circle class="hub" cx="139" cy="108" r="11"/><circle class="hub" cx="342" cy="108" r="11"/><path class="detail" d="M87 85h18m292 6 13 3"/></svg>`}
function overviewPage(){let live=state.models.filter(m=>m.active);let profit=state.lastReport?.profit||0;let units=state.lastReport?.units||0;let salesValue=live.length?money(live.reduce((n,m)=>n+m.price,0)):'—';let carItems=state.models.length?state.models.map(m=>`<div class="vehicle-row"><div class="vehicle-thumb"><svg viewBox="0 0 480 150"><path fill="${m.color}" d="M59 102 73 79q5-8 20-12l67-18 40-30q9-7 25-7h76q16 0 25 10l38 39 48 10q11 3 15 13l9 18q3 8-7 8H67q-14 0-8-8Z"/><circle fill="#29382e" cx="139" cy="108" r="23"/><circle fill="#29382e" cx="342" cy="108" r="23"/></svg></div><div class="vehicle-info"><strong>${escapeHtml(m.name)}</strong><small>${bodyInfo(m.body).name} · ${m.year} · ${money(m.price)}</small></div><span class="vehicle-state">${m.active?'IN PRODUCTION':'RETIRED'}</span><div class="vehicle-right"><strong>${m.soldTotal.toLocaleString()}</strong><small>lifetime units</small></div></div>`).join(''):'<div class="empty-state">Your first car is waiting in the design studio. Give it a name, make it yours, then send it down the line.</div>';
return `${pageHead('A good year to get moving.','Build a company worth remembering — one clever idea, one great car at a time.','COMPANY OVERVIEW')}<section class="overview-grid"><div class="hero-card"><div class="hero-top"><span class="hero-kicker">${live.length?'YOUR LINEUP · '+live.length+' IN PRODUCTION':'THE FIRST CHAPTER · '+state.year}</span><span class="hero-badge">${live.length?'MADE TO MOVE':'INDEPENDENT SINCE '+state.year}</span></div><h2>${live.length?'Made for the long way around.':'Big ideas start in small garages.'}</h2><p>${live.length?`${escapeHtml(live[0].name)} is out on the road. Keep improving the craft and the people behind it.`:'Design your first vehicle, put a team behind it, and take your little garage to the world.'}</p><div class="hero-actions"><button class="btn-light" data-go="${live.length?'market':'design'}">${live.length?'View market report':'Open the design studio'} &nbsp;↗</button><button class="btn-ghost-light" data-go="people">Build the team</button></div><div class="hero-illustration">${carSvg(live[0]?.color||state.draft.color)}</div></div><div class="side-stack"><div class="quick-panel panel"><h3>Make your next move</h3><button class="quick-action" data-go="design"><span class="quick-symbol">◇</span><span>Design a vehicle<small>Shape your next big idea</small></span><span class="quick-arrow">↗</span></button><button class="quick-action" data-go="research"><span class="quick-symbol">⌘</span><span>Invest in research<small>Technology for the road ahead</small></span><span class="quick-arrow">↗</span></button><button class="quick-action" data-go="people"><span class="quick-symbol">♙</span><span>Grow your team<small>Researchers &amp; fixers wanted</small></span><span class="quick-arrow">↗</span></button></div><div class="news-panel panel"><div class="news-title">FROM THE COMPANY JOURNAL · ${state.year}</div><div class="news-item">${state.lastReport?`<b>${escapeHtml(state.lastReport.headline)}</b> ${escapeHtml(state.lastReport.summary)}`:'A fresh ledger, a little workspace, and $2,000 in the bank. Every great motor company has a first day.'}</div></div></div></section><section class="metric-row"><div class="metric-card"><div class="metric-label">TREASURY<i>◈</i></div><div class="metric-value">${money(state.cash)}</div><div class="metric-foot">${state.lastReport?`<span class="${profit>=0?'up':'neutral'}">${profit>=0?'+':''}${money(profit)}</span> last year`:'A little seed capital to start'}</div></div><div class="metric-card"><div class="metric-label">RESEARCH POINTS<i>✳</i></div><div class="metric-value">${state.rp} <span style="font-size:11px;color:#8b9187">RP</span></div><div class="metric-foot">${2+state.researchers*3} earned each year</div></div><div class="metric-card"><div class="metric-label">VEHICLES<i>◇</i></div><div class="metric-value">${state.models.length}</div><div class="metric-foot">${live.length} currently in production</div></div><div class="metric-card"><div class="metric-label">QUALITY<i>✧</i></div><div class="metric-value">${live.length?Math.round(live.reduce((a,m)=>a+m.quality,0)/live.length)+'%':'—'}</div><div class="metric-foot">${state.fixers} fixers on the team</div></div></section><section class="dash-lower"><div class="fleet-panel panel"><div class="panel-head"><h3>Your vehicles</h3><span>${state.models.length} MODEL${state.models.length===1?'':'S'} DESIGNED</span></div>${carItems}</div><div class="side-stack"><div class="fleet-panel panel"><div class="panel-head"><h3>Company at a glance</h3><span>${state.year}</span></div><div class="employee-line"><span>Researchers</span><strong>${state.researchers}</strong></div><div class="employee-line"><span>Fixers</span><strong>${state.fixers}</strong></div><div class="employee-line"><span>Factory capacity</span><strong>${(state.buildings*180).toLocaleString()} / yr</strong></div><div class="employee-line"><span>Markets reached</span><strong>${state.regions.length}</strong></div></div></div></section>`}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

input.newString:
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function designPage(){let d=state.draft,s=draftScores(),body=bodyInfo(d.body),unlocked=bodies.filter(b=>!b.tech||techHas(b.tech));return `${pageHead('Design what comes next.','Every line, every detail, every decision is yours. Build a car that feels like your company.','DESIGN STUDIO')}<div class="studio-layout"><div class="studio-main"><section class="studio-card panel"><div class="panel-head"><div><h3>The design bay</h3><div class="card-sub">A clay model in your chosen finish.</div></div><span class="tag">CONCEPT ${String(state.modelNo).padStart(2,'0')}</span></div><div class="design-preview"><span class="preview-label">SIDE PROFILE · ${escapeHtml(body.name.toUpperCase())}</span><div class="design-car">${carSvg()}</div></div><div class="swatch-row">${palettes.map(p=>`<button class="swatch ${d.color===p.hex?'selected':''}" title="${p.name}" aria-label="${p.name}" style="background:${p.hex}" data-color="${p.hex}"></button>`).join('')}</div></section><section class="studio-card panel"><div class="panel-head"><div><h3>Vehicle blueprint</h3><div class="card-sub">Choose the bones of your next model.</div></div></div><div class="control-row"><div><label class="input-label" for="modelName">MODEL NAME</label><input id="modelName" class="text-input" maxlength="24" value="${escapeHtml(d.name)}" /></div><div><label class="input-label" for="modelBody">VEHICLE CLASS</label><select class="select-input" id="modelBody">${bodies.map(b=>`<option value="${b.id}" ${d.body===b.id?'selected':''} ${b.tech&&!techHas(b.tech)?'disabled':''}>${b.name}${b.tech&&!techHas(b.tech)?' · locked':''}</option>`).join('')}</select></div></div><div class="field-group"><label class="input-label">BODY SHAPE</label><div class="range-line"><span>Elegant &amp; smooth</span><div class="inline-control"><input type="range" min="0" max="100" value="${d.shape}" data-design="shape"><span class="range-val" data-range-value="shape">${d.shape}</span></div><span>Bold &amp; sculpted</span></div></div><div class="field-group"><label class="input-label">CABIN SIZE</label><div class="range-line"><span>Compact</span><div class="inline-control"><input type="range" min="0" max="100" value="${d.size}" data-design="size"><span class="range-val" data-range-value="size">${d.size}</span></div><span>Spacious</span></div></div><div class="field-group"><label class="input-label">INTERIOR COMFORT</label><div class="range-line"><span>Simple</span><div class="inline-control"><input type="range" min="0" max="100" value="${d.interior}" data-design="interior"><span class="range-val" data-range-value="interior">${d.interior}</span></div><span>Premium</span></div></div><div class="field-group"><label class="input-label">TYRE SETUP</label><div class="choice-grid">${[['touring','Touring','Quiet & comfortable'],['sport','Sport','Grip & response'],['utility','Utility','Tough & durable']].map(([id,title,sub])=>`<button class="choice-card ${d.tires===id?'selected':''}" data-tire="${id}"><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div></div><div class="control-row"><div><label class="input-label" for="modelPrice">STICKER PRICE ($)</label><input id="modelPrice" class="text-input" type="number" min="5000" step="500" value="${d.price}" /></div><div class="design-summary"><div class="design-summary-line"><span>Vehicle class</span><strong>${body.name.toUpperCase()}</strong></div><div class="design-summary-line"><span>Factory cost / unit</span><strong>${money(Math.round(d.price*.68))}</strong></div></div></div></section></div><div class="studio-side"><section class="studio-card panel"><div class="panel-head"><div><h3>Independent road test</h3><div class="card-sub">A panel rates your concept for its era.</div></div><span class="tag">${s.quality}% SCORE</span></div><div class="rating-bars">${[['Design',s.design],['Technology',s.technology],['Comfort',s.comfort],['Quality',s.quality]].map(([label,val])=>`<div class="rating-row"><span>${label}</span><div class="rating-track"><div class="rating-fill" style="width:${val}%"></div></div><b>${val}</b></div>`).join('')}</div><hr class="divider"><p class="small-note">${state.fixers?`${state.fixers} fixer${state.fixers===1?'':'s'} help catch design flaws, lift comfort and improve road-test quality.`:'Hire fixers to find errors and polish comfort, fit and finish.'}</p><div class="launch-banner">${state.cash>=650?`Launch cost: <b>${money(650)}</b>. A new model runs for four years before its line retires.`:`You need ${money(650-state.cash)} more to fund a production launch.`}</div><div class="studio-actions"><button class="btn-secondary" data-go="people">Hire fixers</button><button class="btn-primary" id="launchModel" ${state.cash<650?'disabled':''}>Launch model ↗</button></div></section><section class="studio-card panel"><div class="panel-head"><h3>Era-appropriate engineering</h3><span>${state.year}</span></div><p class="small-note">Only technologies invented by ${state.year} can be used. You have researched ${techCount()} technology${techCount()===1?'':'ies'} so far.</p><button class="btn-secondary" style="width:100%;margin-top:8px" data-go="research">Visit research lab ↗</button></section><section class="studio-card panel"><div class="panel-head"><h3>Design advice</h3><span>ROAD TEST PANEL</span></div><p class="small-note">${s.design<55?'The panel wants a more distinctive shape. Sculpt the body or explore a new class.':s.comfort<55?'The cabin could be kinder to its passengers. Invest in interior comfort and touring tyres.':s.technology<55?'A little more innovation would help this model stand apart. Research a new technology.':'The panel sees a thoughtful, well-rounded design with clear potential.'}</p></section></div></div>`}
function refreshDesignPreview(){let preview=document.querySelector('.design-preview');if(preview){preview.querySelector('.design-car').innerHTML=carSvg();preview.querySelector('.preview-label').textContent=`SIDE PROFILE · ${bodyInfo(state.draft.body).name.toUpperCase()}`;let rating=document.querySelector('.studio-side');let old=rating?.innerHTML;if(old){let temp=document.createElement('div');temp.innerHTML=designPage();let next=temp.querySelector('.studio-side');rating.innerHTML=next.innerHTML;bindContent()}}}
document.getElementById('appContent').addEventListener('click',e=>{let go=e.target.closest('[data-go]');if(go){setView(go.dataset.go);return}let color=e.target.closest('[data-color]');if(color){state.draft.color=color.dataset.color;save();render();return}let tire=e.target.closest('[data-tire]');if(tire){state.draft.tires=tire.dataset.tire;save();render();return}let launch=e.target.closest('#launchModel');if(launch)launchDraft()});
document.getElementById('appContent').addEventListener('input',e=>{let el=e.target;if(el.dataset.design){state.draft[el.dataset.design]=Number(el.value);let val=document.querySelector(`[data-range-value="${el.dataset.design}"]`);if(val)val.textContent=el.value;save();updateDesignRatings()}else if(el.id==='modelPrice'){state.draft.price=Math.max(5000,Number(el.value)||5000);save()}});
document.getElementById('appContent').addEventListener('change',e=>{let el=e.target;if(el.id==='modelName'){state.draft.name=el.value.trim()||'Unnamed';save()}if(el.id==='modelBody'){state.draft.body=el.value;save();render()}if(el.id==='modelPrice'){state.draft.price=Math.max(5000,Number(el.value)||5000);save();render()}});
