function launchDraft(){let d={...state.draft,name:state.draft.name.trim()||`Morrow ${String(state.modelNo).padStart(2,'0')}`};let score=draftScores(d);if(state.cash<650){toast('Not enough cash to fund this production launch.');return}if(bodies.find(b=>b.id===d.body)?.tech&&!techHas('truck')){toast('Research the utility vehicle platform first.');return}state.cash-=650;state.models.push({id:`model-${Date.now()}`,name:d.name,body:d.body,color:d.color,price:d.price,quality:score.quality,design:score.design,technology:score.technology,comfort:score.comfort,year:state.year,age:0,soldTotal:0,active:true});state.modelNo++;state.draft={...defaultState().draft,name:`Morrow ${String(state.modelNo).padStart(2,'0')}`};save();render();toast(`${d.name} is on the production line!`)}
function researchPage(){let available=techTree.filter(t=>t.year<=state.year);let locked=techTree.filter(t=>t.year>state.year);return `${pageHead('Tomorrow is built today.','Fund the ideas that make your vehicles safer, smarter and more memorable.','RESEARCH & DEVELOPMENT')}<div class="resource-strip"><div class="resource-box"><span>AVAILABLE POINTS</span><strong>${state.rp} <small style="font:500 9px 'DM Mono';color:#8f958a">RP</small></strong></div><div class="resource-box"><span>ANNUAL OUTPUT</span><strong>${2+state.researchers*3} <small style="font:500 9px 'DM Mono';color:#8f958a">RP / YEAR</small></strong></div><div class="resource-box"><span>TECHNOLOGIES</span><strong>${techCount()} <small style="font:500 9px 'DM Mono';color:#8f958a">RESEARCHED</small></strong></div></div><div class="research-layout"><section class="panel" style="padding:16px"><div class="panel-head"><h3>Research opportunities</h3><span>${available.length} AVAILABLE IN ${state.year}</span></div><div class="research-list">${available.map(t=>{let done=techHas(t.id);let can=state.rp>=t.cost;return `<div class="tech-row"><div class="tech-icon">${t.icon}</div><div class="tech-data"><strong>${t.name}</strong><p>${t.desc}</p><div class="tech-meta">INTRODUCED ${t.year} · ${t.cost} RP · ${t.effect}</div></div><div class="tech-action">${done?'<span class="tag">RESEARCHED</span>':`<button class="${can?'btn-primary':'btn-secondary'}" data-research="${t.id}" ${can?'':'disabled'}>${t.cost} RP &nbsp;↗</button>`}</div></div>`}).join('')}</div>${locked.length?`<div class="section-row"><h3 class="section-title">On the horizon</h3><span class="section-meta">FUTURE TECHNOLOGY</span></div><div class="research-list">${locked.slice(0,4).map(t=>`<div class="tech-row" style="opacity:.72"><div class="tech-icon">${t.icon}</div><div class="tech-data"><strong>${t.name}</strong><p>${t.desc}</p><div class="tech-meta">AVAILABLE IN ${t.year}</div></div><div class="tech-action"><span class="locked-label">${t.year-state.year} YR${t.year-state.year===1?'':'S'} AWAY</span></div></div>`).join('')}</div>`:''}</section><aside class="lab-side panel"><h3>Build your research team</h3><p class="small-note">Researchers turn the calendar into discoveries. Hire more to earn Research Points faster.</p><div class="researcher-count"><span>Researchers on staff</span><strong>${state.researchers}</strong></div><div class="researcher-count"><span>Hire cost</span><strong>${money(450)}</strong></div><div class="researcher-count"><span>Annual salary / person</span><strong>${money(140)}</strong></div><button class="btn-primary" style="width:100%;margin-top:13px" data-hire="researcher" ${state.cash<450?'disabled':''}>Hire a researcher &nbsp;↗</button><div class="insight-card"><strong>Research is era-locked</strong><p>You can only pursue technologies introduced in ${state.year} or earlier. Points carry over, so invest whenever you are ready.</p></div><div class="insight-card"><strong>Next milestone</strong><p>${!techHas('truck')?'Research the utility vehicle platform (2008) to unlock pickups, jeeps and small trucks.':!techHas('electric')?'Electric drive arrives in 2017. Keep advancing and invest in the future.':'Your engineering team is shaping the future of the road.'}</p></div></aside></div>`}
function researchTech(id){let t=techTree.find(x=>x.id===id);if(!t||t.year>state.year||techHas(id))return;if(state.rp<t.cost){toast('Not enough research points yet.');return}state.rp-=t.cost;state.tech.push(id);save();render();toast(`${t.name} is now part of your engineering toolkit.`)}

