ldings} owned</span></div><button class="btn-secondary" data-build="factory" ${state.cash<nextFactoryCost?'disabled':''}>Expand · ${money(nextFactoryCost)}</button></article><article class="building-card"><span class="building-icon">⌘</span><h4>Research lab</h4><p>Researchers work from your main workshop, ready for new discoveries.</p><div class="factory-cap"><i style="width:${Math.min(100,20+state.researchers*18)}%"></i></div><div class="capacity-legend"><span>${state.researchers} researchers</span><span>${2+state.researchers*3} RP / yr</span></div><button class="btn-secondary" data-go="research">Grow your lab ↗</button></article></div></section><section class="team-card panel"><div class="panel-head"><div><h3>Make it official</h3><div class="card-sub">Put your name over the door.</div></div></div><label class="input-label" for="companyName">COMPANY NAME</label><div class="inline-control"><input id="companyName" class="text-input" maxlength="32" value="${escapeHtml(state.company)}"><button class="btn-secondary" id="saveCompany">Save name</button></div></section></div><aside class="team-card panel"><div class="panel-head"><div><h3>Where we do business</h3><div class="card-sub">Open new markets to find more customers.</div></div></div><div class="region-row"><div><strong>Home market</strong><small>Company headquarters</small></div><span class="tag">OPEN</span></div>${regions.map(r=>`<div class="region-row"><div><strong>${r}</strong><small>${state.regions.includes(r)?'Regional sales network':'Expand sales by 15%'}</small></div>${state.regions.includes(r)?'<span class="tag">OPEN</span>':`<button class="btn-secondary" data-region="${r}" ${state.cash<2200?'disabled':''}>Open · ${money(2200)}</button>`}</div>`).join('')}<div class="insight-card"><strong>International ambitions</strong><p>Each new continent increases customer demand by 15%. Building a local network costs ${money(2200)}.</p></div></aside></div>`}
function hire(kind){let researcher=kind==='researcher',cost=researcher?450:350;if(state.cash<cost){toast('Not enough cash to hire right now.');return}state.cash-=cost;if(researcher)state.researchers++;else state.fixers++;save();render();toast(researcher?'A curious mind just joined the lab.':'A sharp eye just joined the workshop.')}
function buildFactory(){let cost=2600+(state.buildings-1)*1800;if(state.cash<cost){toast('Not enough cash to expand the factory.');return}state.cash-=cost;state.buildings++;save();render();toast('New production space is ready.')}
function openRegion(region){if(state.regions.includes(region))return;if(state.cash<2200){toast('Not enough cash to open a new market.');return}state.cash-=2200;state.regions.push(region);save();render();toast(`${region} is now on your map.`)}

