function reviewerCopy(m){let aspects=[['design',m.design],['technology',m.technology],['comfort',m.comfort]].sort((a,b)=>a[1]-b[1]);let weakest=aspects[0][0];let comments={design:'Reviewers want a more memorable shape before they call it a classic.',technology:'The engineering feels a step behind the most forward-thinking models of its year.',comfort:'The cabin is promising, though long journeys could be more comfortable.'};return m.quality>=78?'The panel calls it a standout: confident design, convincing engineering and a cabin people want to spend time in.':m.quality>=62?'A well-rounded effort. It feels competitive for its time, with a few details that make it memorable.':`${comments[weakest]} A focused second generation could win the panel over.`}
function advanceYear(){let currentYear=state.year,active=state.models.filter(m=>m.active);let capacity=state.buildings*180,remaining=capacity;let campaign=state.campaign;let unitTotal=0,profit=0,retired=[];let modelResults=[];for(let i=0;i<active.length;i++){let m=active[i];let baseDemand=clamp(Math.round(42+m.quality*1.02),12,145);let reach=1+(state.regions.length-1)*.14;let priceFactor=clamp(1-(m.price-16000)/80000,.65,1.15);let demand=Math.round(baseDemand*reach*priceFactor*(1+campaign/100));let share=Math.ceil(remaining/(active.length-i));let sold=Math.min(demand,share);remaining-=sold;let margin=Math.max(500,Math.round(m.price*(.11+m.quality*.0012)));let modelProfit=sold*margin;unitTotal+=sold;profit+=modelProfit;m.soldTotal+=sold;m.age++;modelResults.push({name:m.name,sold,profit:modelProfit,quality:m.quality});if(m.age>=4){m.active=false;retired.push(m.name)}}let payroll=state.researchers*140+state.fixers*120+state.buildings*150+120;let net=profit-payroll;state.cash+=net;state.rp+=2+state.researchers*3;state.campaign=0;let head=unitTotal?`${unitTotal.toLocaleString()} vehicles found new homes.`:'A quiet year on the road.';let summary=unitTotal?`${money(profit)} operating margin from ${unitTotal.toLocaleString()} deliveries, less ${money(payroll)} in workshop and team costs.`:`No cars were sold. Annual running costs came to ${money(payroll)}.`;if(retired.length)summary+=` ${retired.join(', ')} ${retired.length===1?'has':'have'} completed its production run.`;let review=active.length?reviewerCopy(active[0]):state.models.length?'The panel looks forward to your next model.':'Your first independent review is waiting for a production launch.';state.lastReport={year:currentYear,units:unitTotal,profit:net,operating:profit,payroll,headline:head,summary,review,models:modelResults,retired};state.history.push({year:currentYear,profit:net,units:unitTotal});state.history=state.history.slice(-20);state.year++;save();render();let models= modelResults.length?`<div class="modal-stat">${modelResults.slice(0,4).map(m=>`<div><small>${escapeHtml(m.name.toUpperCase())} · ${m.quality}% REVIEW</small><strong>${m.sold} SOLD &nbsp;·&nbsp; ${money(m.profit)}</strong></div>`).join('')}</div>`:'';showModal(`${currentYear} · year in review`,`${summary} ${review}`,`Continue to ${state.year}`,()=>{},`<div class="modal-stat"><div><small>NET RESULT</small><strong style="color:${net>=0?'#456d4c':'#b95846'}">${net>=0?'+':''}${money(net)}</strong></div><div><small>RESEARCH EARNED</small><strong>+${2+state.researchers*3} RP</strong></div></div>${models}`)}
render();

